static int parse_values(const char *s, long long out[8]) {
    int count = 0;
    while (*s != '\0' && count < 8) {
        if (*s == '-' || (*s >= '0' && *s <= '9')) {
            char *end = NULL;
            long long v = strtoll(s, &end, 10);
            if (end != s) {
                out[count++] = v;
                s = end;
                continue;
            }
        }
        s++;
    }
    return count;
}

bool isRectangleOverlap(const long long *rec1, int rec1Size,
                        const long long *rec2, int rec2Size) {
    (void)rec1Size;
    (void)rec2Size;
    long long left = rec1[0] > rec2[0] ? rec1[0] : rec2[0];
    long long right = rec1[2] < rec2[2] ? rec1[2] : rec2[2];
    long long bottom = rec1[1] > rec2[1] ? rec1[1] : rec2[1];
    long long top = rec1[3] < rec2[3] ? rec1[3] : rec2[3];
    return left < right && bottom < top;
}

