        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        Pattern p = Pattern.compile("-?\\d+");
        Matcher m = p.matcher(line);
        long[] vals = new long[8];
        int idx = 0;
        while (m.find() && idx < 8) vals[idx++] = Long.parseLong(m.group());
        if (idx != 8) throw new IllegalArgumentException("Expected 8 integer coordinates");
        long[] rec1 = Arrays.copyOfRange(vals, 0, 4);
        long[] rec2 = Arrays.copyOfRange(vals, 4, 8);
        System.out.println(new Solution().isRectangleOverlap(rec1, rec2));
    }
}

